<script setup lang="ts">
import {ref,computed,watch} from 'vue';const props=defineProps<{pattern:any;compact?:boolean}>();const emit=defineEmits(['gene']);const selected=ref(''),kind=ref('all');const focus=ref<any>(null);
const filteredGenes=computed(()=>props.pattern?.genes.filter((g:any)=>kind.value==='all'||g.type===kind.value)||[]);
const graphHeight=computed(()=>Math.max(590,130+Math.max(filteredGenes.value.length,props.pattern?.imagery.length||0)*46));
const centerY=computed(()=>graphHeight.value/2);
const nodes=computed(()=>{if(!props.pattern)return[];const genes=filteredGenes.value,meanings=props.pattern.imagery;const span=graphHeight.value-130;return [...genes.map((g:any,i:number)=>({id:g.code,label:g.name.replace(/〔.*?〕/g,''),type:g.type,x:140,y:65+i*(span/Math.max(genes.length-1,1)),data:g})),...meanings.map((m:any,i:number)=>({id:m.id,label:m.word,type:m.category,x:660,y:65+i*(span/Math.max(meanings.length-1,1)),data:m}))]});
watch(()=>props.pattern?.id,()=>{selected.value='';focus.value=null});
const edges=computed(()=>props.pattern?.relations.filter((r:any)=>nodes.value.some(n=>n.id===r.gene)&&nodes.value.some(n=>n.id===r.imagery))||[]);function xy(id:string){return nodes.value.find(n=>n.id===id)||{x:400,y:290}}function select(n:any){selected.value=selected.value===n.id?'':n.id;focus.value=selected.value?n:null}
const evidence=computed(()=>props.pattern?.relations.filter((r:any)=>r.gene===selected.value||r.imagery===selected.value)||[]);
</script><template><section class="atlas" :class="{compact}"><div class="atlas-heading"><div><span class="kicker">THE THREADS BETWEEN / 纹与意之间</span><h3>一根线条，如何连起一种祝福？</h3></div><span class="graph-legend"><span>{{filteredGenes.length}} 条基因 · {{pattern?.imagery.length||0}} 个意象</span> <i></i> 已确认 <i class="dashed"></i> 候选</span></div><div class="atlas-filters"><button v-for="k in ['all','图元','构图','语义','工艺适配']" :class="{selected:kind===k}" @click="kind=k;selected='';focus=null">{{k==='all'?'全部关系':k}}</button></div><div class="atlas-layout"><svg :viewBox="`0 0 800 ${graphHeight}`" role="img" aria-label="纹样基因与文化意象关系图"><defs><radialGradient id="nodeGlow"><stop stop-color="#9ebca2" stop-opacity=".15"/><stop offset="1" stop-color="#9ebca2" stop-opacity="0"/></radialGradient></defs><circle cx="400" :cy="centerY" r="180" fill="url(#nodeGlow)"/><g class="graph-orbits"><circle cx="400" :cy="centerY" r="80"/><circle cx="400" :cy="centerY" r="118"/><path :d="`M400 ${centerY-165}V${centerY+165}M235 ${centerY}H565`"/></g><g v-for="e in edges" :key="e.id" :class="['graph-edge',{dim:selected&&selected!==e.gene&&selected!==e.imagery,lit:selected===e.gene||selected===e.imagery,candidate:e.status!=='已确认'}]"><path :d="`M${xy(e.gene).x+12},${xy(e.gene).y} C350,${xy(e.gene).y} 450,${xy(e.imagery).y} ${xy(e.imagery).x-12},${xy(e.imagery).y}`"/><title>{{e.evidence}} · {{e.weight}}</title></g><g class="graph-center"><circle cx="400" :cy="centerY" r="53"/><text x="400" :y="centerY-4">{{pattern?.id}}</text><text x="400" :y="centerY+19" class="graph-subtitle">形 · 意 · 器</text></g><g v-for="n in nodes" :key="n.id" tabindex="0" role="button" :aria-label="n.label" @click="select(n)" @keydown.enter="select(n)" :class="['graph-node',{chosen:selected===n.id}]" :transform="`translate(${n.x} ${n.y})`"><rect :x="n.x<400?-135:-20" y="-22" width="155" height="52" fill="transparent"/><circle r="6"/><circle class="node-ring" r="15"/><text :x="n.x<400?-22:22" y="4" :text-anchor="n.x<400?'end':'start'">{{n.label}}</text><text class="node-type" :x="n.x<400?-22:22" y="21" :text-anchor="n.x<400?'end':'start'">{{n.type}}</text></g><text class="graph-axis" x="100" :y="graphHeight-20">基因 · 可见的形</text><text class="graph-axis" x="600" :y="graphHeight-20">意象 · 可读的意</text></svg><aside class="atlas-reading"><template v-if="focus"><span class="kicker">{{focus.type}}</span><h3>{{focus.label}}</h3><p v-if="focus.data.structure||focus.data.evidence">{{focus.data.structure||focus.data.evidence}}</p><div v-for="r in evidence" :key="r.id" class="evidence-line"><span>{{r.status}} <b>{{Math.round(r.weight*100)}}<small>映射权重</small></b></span><p>{{r.evidence}}</p><div class="evidence-meter"><i :style="{width:(r.weight*100)+'%'}"></i></div></div><p v-if="!evidence.length">此条目尚无直接意象映射，不能据此推断文化含义。</p><button v-if="focus.data.code?.startsWith('M-')" class="link-action" @click="emit('gene',focus.data)">查看图元档案 ↗</button></template><template v-else><span class="graph-intro-symbol">经<br>纬</span><h3>点击节点，循线知意。</h3><p>左侧是图元、构图、语义与工艺；右侧是文化、感性、场景与地域意象。</p><p>每条连线都有文档依据。权重表示资料中的关联强度，不代表历史事实的概率。</p></template></aside></div></section></template>
